src/test/java/in/grocery/catalog/web/PingControllerTest.java<pre><code>package in.grocery.catalog.web;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.test.web.servlet.assertj.MockMvcTester;

@WebMvcTest(PingController.class)
class PingControllerTest {

    @Autowired
    MockMvcTester mvc; // (1)!

    @Test
    void pingReturnsUp() {
        assertThat(mvc.get().uri("/ping"))
                .hasStatusOk()
                .bodyJson()
                .extractingPath("$.status")
                .isEqualTo("UP");
    }
}
</code></pre> <ol> <li>AssertJ-style MockMvc, available since Spring Framework 6.2 / Boot 3.4.</li> </ol> <p>Verify — test annotation packages in Boot 4</p> <p>With modularization, some test auto-configuration annotations (such as <code>@WebMvcTest</code>) moved to technology-specific modules and packages in Boot 4. If an import does not resolve, check the migration guide for the new package.</p>

