in/grocery/common/env/MountedSecretsEnvironmentPostProcessor.java<pre><code>package in.grocery.common.env;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import java.util.stream.Stream;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.env.EnvironmentPostProcessor;
import org.springframework.core.Ordered;
import org.springframework.core.env.ConfigurableEnvironment;
import org.springframework.core.env.MapPropertySource;

/**
 * Reads /var/run/secrets/grocery/&lt;key&gt; files (one value per file) into a property source.
 * File name "razorpay.key-secret" becomes property "grocery.secrets.razorpay.key-secret".
 */
public class MountedSecretsEnvironmentPostProcessor implements EnvironmentPostProcessor, Ordered {

    static final String DIR_PROPERTY = "grocery.secrets.dir";
    static final String DEFAULT_DIR = "/var/run/secrets/grocery";

    @Override
    public void postProcessEnvironment(ConfigurableEnvironment env, SpringApplication app) {
        Path dir = Path.of(env.getProperty(DIR_PROPERTY, DEFAULT_DIR));
        if (!Files.isDirectory(dir)) {
            return;                                                            // (1)!
        }
        Map&lt;String, Object&gt; values = new HashMap&lt;&gt;();
        try (Stream&lt;Path&gt; files = Files.list(dir)) {
            files.filter(Files::isRegularFile).forEach(f -&gt; {
                try {
                    values.put("grocery.secrets." + f.getFileName(), Files.readString(f).strip());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            });
        } catch (IOException e) {
            throw new UncheckedIOException("Cannot read secrets from " + dir, e);
        }
        env.getPropertySources().addLast(new MapPropertySource("mountedSecrets", values)); // (2)!
    }

    @Override
    public int getOrder() {
        return Ordered.LOWEST_PRECEDENCE;
    }
}
</code></pre> <ol> <li>Local development has no mounted directory — skip silently.</li> <li><code>addLast</code> — env vars and <code>application.yml</code> can still override for local testing. Use <code>addFirst</code> if secrets must win.</li> </ol> src/main/resources/META-INF/spring.factories<pre><code>org.springframework.boot.env.EnvironmentPostProcessor=\
in.grocery.common.env.MountedSecretsEnvironmentPostProcessor
</code></pre> <p>Verify — package in Boot 4</p> <p>Spring Boot 4 relocated <code>EnvironmentPostProcessor</code> to the <code>org.springframework.boot</code> package (the old type is deprecated). Check the 4.0 migration guide and update both the import and the <code>spring.factories</code> key.</p> <p>Built-in alternative</p> <p>Boot already supports mounted directories via config trees: <code>spring.config.import=configtree:/var/run/secrets/grocery/</code>. Write an <code>EnvironmentPostProcessor</code> only when you need custom logic (decryption, naming conventions, an external API). Chapter 06 compares both.</p>

