in/grocery/order/web/OrderMdcInterceptor.java<pre><code>package in.grocery.order.web;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import org.slf4j.MDC;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;

@Component
class OrderMdcInterceptor implements HandlerInterceptor {

    @Override
    public boolean preHandle(HttpServletRequest req, HttpServletResponse res, Object handler) {
        @SuppressWarnings("unchecked")
        Map&lt;String, String&gt; vars = (Map&lt;String, String&gt;) req.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (vars != null &amp;&amp; vars.containsKey("orderId")) {
            MDC.put("orderId", vars.get("orderId"));                             // (1)!
        }
        String seller = req.getHeader("X-Seller-Id");
        if (seller != null &amp;&amp; seller.matches("S-[0-9]{1,10}")) {
            MDC.put("sellerId", seller);
        }
        return true;
    }

    @Override
    public void afterCompletion(HttpServletRequest req, HttpServletResponse res, Object handler, Exception ex) {
        MDC.remove("orderId");                                                   // (2)!
        MDC.remove("sellerId");
    }
}
</code></pre> <ol> <li>Every log line during <code>/orders/{orderId}/...</code> requests carries the order ID — no need to repeat it in each message.</li> <li><code>afterCompletion</code> runs even when the handler throws. Remove only your keys; don't <code>MDC.clear()</code> other components' entries.</li> </ol> <p>Register it (Chapter 08 covers <code>WebMvcConfigurer</code> in detail):</p> WebConfig.java<pre><code>@Configuration(proxyBeanMethods = false)
class WebConfig implements WebMvcConfigurer {
    private final OrderMdcInterceptor mdc;
    WebConfig(OrderMdcInterceptor mdc) { this.mdc = mdc; }
    @Override public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(mdc).addPathPatterns("/api/orders/**");
    }
}
</code></pre>

