        return jdbc.sql("""
                        select id, order_ref, customer_id, status, total, placed_at
                        from customer_order where customer_id = :cid
                        order by placed_at desc limit :limit
                        """)
                .param("cid", customerId)
                .param("limit", Math.min(limit, 100))
                .query(SUMMARY)
                .list();
