in/grocery/order/service/OrderCancellationService.java<pre><code>package in.grocery.order.service;

import in.grocery.order.domain.Order;
import in.grocery.order.event.OrderCancelled;
import in.grocery.order.repository.OrderRepository;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderCancellationService {

    private final OrderRepository orders;
    private final ApplicationEventPublisher events;

    public OrderCancellationService(OrderRepository orders, ApplicationEventPublisher events) {
        this.orders = orders;
        this.events = events;
    }

    @Transactional                                                            // (1)!
    public void cancel(String orderRef, String reason) {
        Order order = orders.findByOrderRef(orderRef)
                .orElseThrow(() -&gt; new OrderNotFoundException(orderRef));
        order.cancel();                                                       // (2)!
        events.publishEvent(new OrderCancelled(orderRef, reason));            // (3)!
    }

    @Transactional(readOnly = true)                                           // (4)!
    public Order view(String orderRef) {
        return orders.findByOrderRef(orderRef).orElseThrow(() -&gt; new OrderNotFoundException(orderRef));
    }
}
</code></pre> <ol> <li>The whole operation is atomic: status change + any other writes.</li> <li>No <code>save()</code> — dirty checking flushes at commit (Chapter 13).</li> <li>Published inside the transaction; <code>@TransactionalEventListener</code> subscribers run after commit.</li> <li>Read-only: no dirty checking, replica-routable, intent obvious.</li> </ol>

