in/grocery/order/security/ApiKeyAuthFilter.java<pre><code>package in.grocery.order.security;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.List;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.web.authentication.WebAuthenticationDetailsSource;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

@Component
public class ApiKeyAuthFilter extends OncePerRequestFilter {

    public interface ApiKeyService {
        /** Returns the seller id for a valid key (constant-time compare of a hashed key), or empty. */
        java.util.Optional&lt;String&gt; sellerFor(String apiKey);
    }

    private final ApiKeyService apiKeys;

    public ApiKeyAuthFilter(ApiKeyService apiKeys) {
        this.apiKeys = apiKeys;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain)
            throws ServletException, IOException {
        String key = req.getHeader("X-Seller-Api-Key");
        if (key != null &amp;&amp; SecurityContextHolder.getContext().getAuthentication() == null) {
            apiKeys.sellerFor(key).ifPresent(sellerId -&gt; {
                var auth = UsernamePasswordAuthenticationToken.authenticated(                 // (1)!
                        sellerId, null, List.of(new SimpleGrantedAuthority("SCOPE_seller-integration")));
                auth.setDetails(new WebAuthenticationDetailsSource().buildDetails(req));
                var context = SecurityContextHolder.createEmptyContext();                     // (2)!
                context.setAuthentication(auth);
                SecurityContextHolder.setContext(context);
            });
        }
        try {
            chain.doFilter(req, res);
        } finally {
            SecurityContextHolder.clearContext();                                             // (3)!
        }
    }
}
</code></pre> <ol> <li>Authenticated token with no credentials retained.</li> <li>Create a fresh context rather than mutating the existing one (required since Security 5.8/6).</li> <li>Stateless chain: clear the context so nothing leaks to the next request on a pooled thread.</li> </ol> <p>Store API keys hashed</p> <p>Keep <code>sha256(key)</code> (with a per-seller salt or an HMAC) in the database, compare in constant time, support rotation with two active keys, and log the key id, never the key. Better still, move sellers to OAuth2 client credentials (Chapter 18).</p>

in/grocery/order/security/OrderAccess.java<pre><code>package in.grocery.order.security;

import in.grocery.order.repository.OrderRepository;
import java.util.function.Supplier;
import org.springframework.security.authorization.AuthorizationDecision;
import org.springframework.security.authorization.AuthorizationManager;
import org.springframework.security.core.Authentication;
import org.springframework.security.web.access.intercept.RequestAuthorizationContext;
import org.springframework.stereotype.Component;

@Component("orderAccess")
public class OrderAccess implements AuthorizationManager&lt;RequestAuthorizationContext&gt; {       // (1)!

    private final OrderRepository orders;

    public OrderAccess(OrderRepository orders) {
        this.orders = orders;
    }

    @Override
    public AuthorizationDecision check(Supplier&lt;Authentication&gt; authentication, RequestAuthorizationContext context) {
        Authentication auth = authentication.get();
        if (auth == null || !auth.isAuthenticated()) return new AuthorizationDecision(false);
        if (hasRole(auth, "ROLE_OPS")) return new AuthorizationDecision(true);                 // (2)!

        String orderRef = context.getVariables().get("orderRef");                              // (3)!
        return new AuthorizationDecision(orders.existsByOrderRefAndCustomerId(orderRef, auth.getName()));
    }

    /** For @PreAuthorize("@orderAccess.canCancel(#orderRef, authentication)") */
    public boolean canCancel(String orderRef, Authentication auth) {
        return hasRole(auth, "ROLE_OPS")
                || orders.existsByOrderRefAndCustomerId(orderRef, auth.getName());
    }

    private static boolean hasRole(Authentication auth, String role) {
        return auth.getAuthorities().stream().anyMatch(a -&gt; a.getAuthority().equals(role));
    }
}
</code></pre> <ol> <li>Implementing <code>AuthorizationManager</code> makes the rule usable in the DSL and as a bean in SpEL.</li> <li>Operations staff bypass ownership — a deliberate, reviewable exception.</li> <li>URI template variables are available in the authorization context.</li> </ol> Using it in the chain<pre><code>.authorizeHttpRequests(a -&gt; a
    .requestMatchers("/api/orders/{orderRef}/**").access(orderAccess)
    .anyRequest().authenticated())
</code></pre> <p>Prefer owner-scoped queries</p> <p><code>findByOrderRefAndCustomerId(...)</code> needs no extra query and returns 404 rather than 403, revealing nothing about existence. Use the <code>AuthorizationManager</code> when the rule must apply to many endpoints or when the handler can't easily scope its query.</p>

