                            "default-src 'self'; frame-ancestors 'none'; object-src 'none'"))
                    .httpStrictTransportSecurity(hsts -&gt; hsts.includeSubDomains(true).maxAgeInSeconds(31536000)))
            .authorizeHttpRequests(a -&gt; a.anyRequest().hasRole("OPS"))
            .formLogin(Customizer.withDefaults())
