in/grocery/identity/security/OtpRateLimiter.java<pre><code>package in.grocery.identity.security;

import java.time.Duration;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

@Component
public class OtpRateLimiter {

    private final StringRedisTemplate redis;

    public OtpRateLimiter(StringRedisTemplate redis) {
        this.redis = redis;
    }

    /** @return true if the action is allowed. Fixed window; good enough for OTP flows. */
    public boolean allow(String bucket, String key, int limit, Duration window) {
        String redisKey = "rl:" + bucket + ":" + key;
        Long count = redis.opsForValue().increment(redisKey);                                    // (1)!
        if (count != null &amp;&amp; count == 1L) {
            redis.expire(redisKey, window);
        }
        return count != null &amp;&amp; count &lt;= limit;
    }
}
</code></pre> <ol> <li>Atomic increment in Redis; shared across pods. Apply two buckets: OTP requests per mobile (e.g. 3 per 10 min) and verification attempts per mobile (5 per 15 min), plus a per-IP limit to blunt enumeration. Chapter 26 covers proper rate limiting and bulkheads.</li> </ol>

