in/grocery/pricing/service/PricingService.java<pre><code>package in.grocery.pricing.service;

import java.util.List;
import org.springframework.cache.annotation.CacheConfig;
import org.springframework.cache.annotation.CacheEvict;
import org.springframework.cache.annotation.CachePut;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;

@Service
@CacheConfig(cacheNames = "price")
public class PricingService {

    private final PriceRepository prices;
    private final GstCalculator gst;

    public PricingService(PriceRepository prices, GstCalculator gst) {
        this.prices = prices;
        this.gst = gst;
    }

    @Cacheable(key = "#sku + '|' + #pincode",                                     // (1)!
               condition = "#pincode != null",                                    // (2)!
               unless = "#result == null || #result.promotional()",               // (3)!
               sync = true)                                                       // (4)!
    public PriceView priceFor(String sku, String pincode) {
        return prices.findPrice(sku, pincode).map(p -&gt; PriceView.of(p, gst)).orElse(null);
    }

    @CachePut(key = "#sku + '|' + #pincode")                                      // (5)!
    public PriceView refresh(String sku, String pincode) {
        return prices.findPrice(sku, pincode).map(p -&gt; PriceView.of(p, gst)).orElse(null);
    }

    @CacheEvict(key = "#sku + '|' + #pincode")
    public void evict(String sku, String pincode) {}

    @CacheEvict(allEntries = true)
    public void evictAll() {}
}
</code></pre> <ol> <li>Explicit key including every dimension that changes the result.</li> <li>Don't cache when a required dimension is missing.</li> <li>Don't cache flash-sale prices that change minute to minute.</li> <li>One computation per key per JVM under concurrency.</li> <li><code>@CachePut</code> always executes and refreshes the entry — used by the invalidation listener (6.2).</li> </ol> <p><code>sync = true</code> limitations</p> <p><code>sync</code> can't be combined with <code>unless</code>, multiple cache names or <code>@CachePut</code> on the same method, and its guarantee is per JVM unless the cache implementation locks globally (Redis needs a locking cache writer). Chapter 26's bulkheads and 6.3's stale-while-revalidate cover the distributed case.</p>

