in/grocery/platform/amqp/ConfirmingRabbitConfig.java<pre><code>package in.grocery.platform.amqp;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.amqp.rabbit.connection.ConnectionFactory;
import org.springframework.amqp.rabbit.core.RabbitTemplate;
import org.springframework.amqp.support.converter.MessageConverter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration(proxyBeanMethods = false)
public class ConfirmingRabbitConfig {

    private static final Logger log = LoggerFactory.getLogger(ConfirmingRabbitConfig.class);

    @Bean
    RabbitTemplate rabbitTemplate(ConnectionFactory factory, MessageConverter converter,
                                  OutboxRepository outbox, io.micrometer.core.instrument.MeterRegistry meters) {
        RabbitTemplate template = new RabbitTemplate(factory);
        template.setMessageConverter(converter);
        template.setMandatory(true);                                                      // (1)!

        template.setConfirmCallback((correlation, ack, cause) -&gt; {                        // (2)!
            String id = correlation == null ? "unknown" : correlation.getId();
            if (ack) {
                outbox.markSent(id);
            } else {
                log.error("Broker rejected message {}: {}", id, cause);
                meters.counter("grocery.amqp.nack").increment();
            }
        });

        template.setReturnsCallback(returned -&gt; {                                          // (3)!
            log.error("Unroutable message: exchange={} routingKey={} reply={}",
                    returned.getExchange(), returned.getRoutingKey(), returned.getReplyText());
            meters.counter("grocery.amqp.unroutable", "exchange", returned.getExchange()).increment();
        });
        return template;
    }
}
</code></pre> <ol> <li>Without <code>mandatory</code>, a message whose routing key matches no binding is silently discarded — a typo in a routing key becomes lost work with no error anywhere.</li> <li>Outbox rows are marked sent only when the broker confirms (Chapter 23's relay pattern, AMQP flavour).</li> <li>Unroutable messages are an operational alert, not a debug log.</li> </ol>

