import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.stereotype.Component;

@Component("razorpay")
public class RazorpayHealthIndicator implements HealthIndicator {

    private final CircuitBreakerRegistry breakers;

    @Override
    public Health health() {
        var state = breakers.circuitBreaker("razorpay").getState();
        return switch (state) {
            case CLOSED -&gt; Health.up().withDetail("breaker", state).build();
            case HALF_OPEN -&gt; Health.up().withDetail("breaker", state).build();
            default -&gt; Health.status("DEGRADED")                                 // (1)!
                    .withDetail("breaker", state)
                    .withDetail("impact", "Payments unavailable; checkout returns 503")
                    .build();
        };
    }
}
</code></pre> <ol> <li>A custom status that is not <code>DOWN</code>: the pod keeps serving (Chapter 26), but humans see the impact immediately. Map custom statuses to HTTP codes with <code>management.endpoint.health.status.http-mapping</code> if needed, and keep this indicator out of the readiness group.</li> </ol>

