in/grocery/platform/observability/MetricsConfig.java<pre><code>package in.grocery.platform.observability;

import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.config.MeterFilter;
import io.micrometer.core.instrument.distribution.DistributionStatisticConfig;
import java.time.Duration;
import org.springframework.boot.actuate.autoconfigure.metrics.MeterRegistryCustomizer;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration(proxyBeanMethods = false)
public class MetricsConfig {

    @Bean
    MeterRegistryCustomizer&lt;MeterRegistry&gt; commonTags(
            @Value("${spring.application.name}") String app,
            @Value("${grocery.env:local}") String env,
            @Value("${GROCERY_REGION:ap-south-1}") String region,
            org.springframework.boot.info.BuildProperties build) {
        return registry -&gt; registry.config().commonTags(                          // (1)!
                "application", app, "env", env, "region", region, "version", build.getVersion());
    }

    @Bean
    MeterFilter cardinalityGuard() {
        return MeterFilter.maximumAllowableTags("http.server.requests", "uri", 200,   // (2)!
                MeterFilter.deny());
    }

    @Bean
    MeterFilter sloHistograms() {
        return new MeterFilter() {
            @Override
            public DistributionStatisticConfig configure(io.micrometer.core.instrument.Meter.Id id,
                                                         DistributionStatisticConfig config) {
                if (id.getName().startsWith("http.server.requests")
                        || id.getName().startsWith("grocery.checkout")) {
                    return DistributionStatisticConfig.builder()
                            .percentilesHistogram(true)                                // (3)!
                            .serviceLevelObjectives(
                                    Duration.ofMillis(200).toNanos(),
                                    Duration.ofMillis(500).toNanos(),
                                    Duration.ofSeconds(1).toNanos(),
                                    Duration.ofSeconds(2).toNanos())
                            .build().merge(config);
                }
                return config;
            }
        };
    }

    @Bean
    MeterFilter denyNoisyMeters() {
        return MeterFilter.deny(id -&gt; id.getName().startsWith("tomcat.sendfile"));      // (4)!
    }
}
</code></pre> <ol> <li>Every metric carries application, environment, region and version — the tags dashboards slice by, and the ones that let you spot "only v1.42 pods are slow".</li> <li>Cardinality guard: after 200 distinct <code>uri</code> values, new ones are dropped. Protects against a mis-templated path leaking ids into metrics.</li> <li>Histograms enable accurate percentile and SLO queries in Prometheus; explicit SLO buckets make burn-rate alerting cheap.</li> <li>Trim metrics nobody uses — storage and scrape cost are real.</li> </ol>

